#!/usr/bin/env node
// 依赖安装兼容入口：优先使用 Bun（与 bun.lock 严格对齐，
// --frozen-lockfile 保证可复现）；当运行环境没有 Bun 时回退到 npm，
// 使 CI 在仅预装 Node 的 runner 上也能完成安装。
// 用法：node scripts/install-deps.mjs   （由 package.json 的 install-dependencies 调用）
import { spawnSync } from 'node:child_process';
import { existsSync } from 'node:fs';

function hasCommand(cmd) {
  const probe = process.platform === 'win32'
    ? spawnSync('where', [cmd], { stdio: 'ignore' })
    : spawnSync('sh', ['-c', `command -v ${cmd}`], { stdio: 'ignore' });
  return probe.status === 0;
}

function run(cmd, args) {
  console.log(`\n[install-deps] $ ${cmd} ${args.join(' ')}`);
  const res = spawnSync(cmd, args, { stdio: 'inherit', shell: process.platform === 'win32' });
  return res.status ?? 1;
}

const hasBunLock = existsSync('bun.lock') || existsSync('bun.lockb');
const hasPkgLock = existsSync('package-lock.json');

let code;
if (hasCommand('bun')) {
  console.log('[install-deps] 检测到 Bun，使用 Bun 安装（--frozen-lockfile）');
  code = run('bun', hasBunLock ? ['install', '--frozen-lockfile'] : ['install']);
} else {
  console.log('[install-deps] 未检测到 Bun，回退到 npm 安装');
  // 有 package-lock.json 时用 npm ci 保证可复现，否则用 npm install。
  code = run('npm', hasPkgLock ? ['ci', '--no-audit', '--no-fund'] : ['install', '--no-audit', '--no-fund']);
  if (code !== 0 && hasPkgLock) {
    console.warn('[install-deps] npm ci 失败，改用 npm install 重试');
    code = run('npm', ['install', '--no-audit', '--no-fund']);
  }
}

process.exit(code);

