#!/usr/bin/env node
// 依赖安装兼容入口：优先使用 Bun（与 bun.lock 严格对齐，--frozen-lockfile 保证可复现）；
// 当运行环境没有 Bun 时回退到 npm，使 CI 在仅预装 Node 的 runner 上也能完成安装。
// 用法：node scripts/install-deps.mjs   （由 package.json 的 install-dependencies 调用）
import { spawnSync } from 'node:child_process';
import { existsSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');

function hasCommand(cmd) {
  const probe = process.platform === 'win32'
    ? spawnSync('where', [cmd], { stdio: 'ignore' })
    : spawnSync('sh', ['-c', `command -v ${cmd}`], { stdio: 'ignore' });
  return probe.status === 0;
}

function run(cmd, args, cwd = ROOT) {
  console.log(`\n[install-deps] $ ${cmd} ${args.join(' ')}   (cwd=${cwd})`);
  const res = spawnSync(cmd, args, { stdio: 'inherit', cwd, shell: process.platform === 'win32' });
  return res.status ?? 1;
}

const hasBunLock = existsSync(join(ROOT, 'bun.lock')) || existsSync(join(ROOT, 'bun.lockb'));
const hasPkgLock = existsSync(join(ROOT, 'package-lock.json'));
const testingDir = join(ROOT, 'tools', 'testing');

let code;
if (hasCommand('bun')) {
  console.log('[install-deps] 检测到 Bun，使用 Bun 安装（--frozen-lockfile）');
  code = run('bun', hasBunLock ? ['install', '--frozen-lockfile'] : ['install']);
} else {
  console.log('[install-deps] 未检测到 Bun，回退到 npm 安装');
  // 1) 根项目安装。
  //    DCloud 系包存在 peer 版本偏差（如 @dcloudio/types 3.4.32 vs uni-app 期望 3.4.31），
  //    Bun 默认宽松解析可通过，npm 严格模式会 ERESOLVE 直接失败，故统一带 --legacy-peer-deps。
  const npmArgs = ['--no-audit', '--no-fund', '--legacy-peer-deps'];
  code = run('npm', [hasPkgLock ? 'ci' : 'install', ...npmArgs]);
  if (code !== 0 && hasPkgLock) {
    console.warn('[install-deps] npm ci 失败，改用 npm install 重试');
    code = run('npm', ['install', ...npmArgs]);
  }
  if (code !== 0) process.exit(code);

  // 2) 测试工具链独立安装。
  //    测试工具链需要 vite@8 与 vitest@5，而应用根使用 vite@5（uni-app 要求），版本冲突。
  //    Bun 通过 workspace 各自嵌套 node_modules 隔离；npm 在 workspace 模式下会强制把
  //    vitest 提升到根目录，导致 vitest 解析到根的 vite@5 而启动失败。
  //    这里用 --workspaces=false 让 npm 把 tools/testing 当作独立项目安装，得到自带的
  //    vite@8 + vitest@5；同时因目录仍位于仓库内，vue 等依赖可向上解析到根 node_modules。
  //    注意：不改动根 package.json 的 workspaces 字段，从而不影响 Bun / bun.lock 的可复现安装。
  if (existsSync(join(testingDir, 'package.json'))) {
    console.log('[install-deps] 安装测试工具链（独立 node_modules，避免 vite 版本冲突）');
    const testCode = run('npm', ['install', ...npmArgs, '--workspaces=false'], testingDir);
    if (testCode !== 0) {
      console.warn('[install-deps] 测试工具链安装失败（不影响应用构建）');
    }
  }
}

process.exit(code);

